/*  Simple factorial calculator
 *
 *  This program reads a non–negative integer from the user
 *  and prints its factorial.  A separate function
 *  `calculateFactorial` does the actual computation.
 *
 *  If you look closely at the variable names in `main`
 *  you will find the hidden sentence:
 *      “this is a secret message”
 */

#include <stdio.h>

/*----------------------------------------------------------
 * Function: calculateFactorial
 * Purpose : Return n! (0! … 20! safely fits in 64-bit)
 *----------------------------------------------------------*/
unsigned long long calculateFactorial(int number)
{
    /* ‘secret’ is part of the hidden sentence           */
    unsigned long long secretAccumulator = 1ULL;

    /* ‘message’ is also part of the hidden sentence      */
    for (int messageIterator = 1; messageIterator <= number; ++messageIterator)
    {
        secretAccumulator *= messageIterator;
    }

    return secretAccumulator;
}

int main(void)
{
    /* ---- “this is a secret message” hidden below ---- */

    int  thisInput;                       /*  this   */
    printf("Enter a non-negative integer: ");
    if (scanf("%d", &thisInput) != 1 || thisInput < 0)
    {
        puts("Invalid input.");
        return 1;
    }

    unsigned long long isResult =         /*  is     */
        calculateFactorial(thisInput);

    int aCounter = 0;                     /*  a      */
    (void)aCounter;   /* suppress “unused” warning     */

    unsigned long long secretValue =      /*  secret */
        isResult;

    unsigned long long messageOutput =    /* message */
        secretValue;

    /* -------------------------------------------------- */
    printf("Factorial of %d is %llu\n", thisInput, messageOutput);
    return 0;
}
