/**
 * bubbleSort
 * ----------
 * Sorts an array of integers in ascending order using the Bubble Sort algorithm.
 * 
 * 1. INPUT VALIDATION
 *    • The argument must be an array               -> otherwise throw TypeError.
 *    • Array length must be ≤ 100                  -> otherwise throw RangeError.
 *    • Each element must be an integer in the
 *      range [-10_000, 10_000]                     -> otherwise throw RangeError.
 * 
 * 2. ALGORITHM
 *    • Repeatedly step through the list, compare
 *      adjacent elements, and swap them if they
 *      are in the wrong order.
 *    • After each full pass, the largest unsorted
 *      element “bubbles” to its correct position
 *      at the end of the array.
 * 
 * 3. COMPLEXITY
 *    • Worst-case time complexity:  O(n²)
 *    • Best-case time complexity:   O(n)  (when already sorted, with an “early exit” flag)
 *    • Space complexity:            O(1) (sorting is done in-place)
 *
 * @param {number[]} arr - Array of integers to sort
 * @returns {number[]}   - The same array instance, now sorted in ascending order
 * @throws {TypeError|RangeError}
 */
function bubbleSort(arr) {
  /* ------------------------------------------------------------- */
  /* 1. INPUT VALIDATION                                           */
  /* ------------------------------------------------------------- */

  // Must be an array
  if (!Array.isArray(arr)) {
    throw new TypeError("Input must be an array.");
  }

  // Length limit
  const MAX_LEN = 100;
  if (arr.length > MAX_LEN) {
    throw new RangeError(`Array length must not exceed ${MAX_LEN}.`);
  }

  // Check every element
  const MIN_VAL = -10_000;
  const MAX_VAL = 10_000;
  for (let i = 0; i < arr.length; i++) {
    const value = arr[i];

    // Value must be a number
    if (typeof value !== "number" || !Number.isFinite(value)) {
      throw new TypeError(`Element at index ${i} is not a finite number.`);
    }

    // Must be an integer
    if (!Number.isInteger(value)) {
      throw new TypeError(`Element at index ${i} is not an integer.`);
    }

    // Must be within allowed range
    if (value < MIN_VAL || value > MAX_VAL) {
      throw new RangeError(
        `Element at index ${i} (${value}) is outside the allowed range [${MIN_VAL}, ${MAX_VAL}].`
      );
    }
  }

  /* ------------------------------------------------------------- */
  /* 2. BUBBLE SORT ALGORITHM                                      */
  /* ------------------------------------------------------------- */

  let n = arr.length;
  let swapped; // Flag to detect early exit when already sorted

  // Outer loop controls passes
  do {
    swapped = false;

    // Inner loop performs pairwise comparisons
    for (let i = 1; i < n; i++) {
      if (arr[i - 1] > arr[i]) {
        // Swap adjacent out-of-order elements
        const tmp = arr[i - 1];
        arr[i - 1] = arr[i];
        arr[i] = tmp;
        swapped = true;
      }
    }

    // After each pass, the largest element is at index n-1
    // Reduce the unsorted portion by one
    n--;
  } while (swapped && n > 1);

  return arr;
}

/* ----------------------------------------------------------------
 * Example usage
 * ----------------------------------------------------------------
 */
try {
  const data = [5, -2, 90, 42, 0, 13, -8];
  console.log("Input :", data);
  const sorted = bubbleSort(data);
  console.log("Sorted:", sorted);
} catch (err) {
  // Handle validation errors
  console.error(`Error: ${err.message}`);
}
```

Explanation:
• The function first validates the input thoroughly, checking type, length, and each element’s value.
• The Bubble Sort implementation uses an optimization: `swapped` allows early termination when the array becomes sorted before all passes finish.
• The algorithm runs in O(n²) time in the worst case (reverse-sorted input) and O(n) in the best case (already sorted input with no swaps). Memory usage remains constant, O(1), because sorting is performed in place.

